import csv
import sys

def calculate_average(filename, column_name):
    total = 0
    count = 0

    with open(filename, 'r') as file:
        reader = csv.DictReader(file)
        for row in reader:
            try:
                value = float(row[column_name])
                total += value
                count += 1
            except (ValueError, KeyError) as e:
                print(f"Skipping row: {e}")

    if count > 0:
        average = total / count
        print(f"Average of {column_name}: {average:.2f}")
    else:
        print("No valid data found")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python calculate_average.py <filename> <column_name>")
        sys.exit(1)

    calculate_average(sys.argv[1], sys.argv[2])
